package Control_Flow_Statements;

public class Switch_Case_1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int letter='A';
		
		switch (letter){
		case 'a':
			System.out.println("Lowercase Letter");
			break;
			
		case 'A':
			System.out.println("Uppercase Letter");
			break;
		}

	}

}
